<?php
if(request_checkout_enabled()){require __DIR__.'/request-checkout.php';return;}
$plan=one('SELECT p.*,c.name AS carrier_name,c.active AS carrier_active,c.slug FROM plans p JOIN carriers c ON c.id=p.carrier_id WHERE p.id=?',[(int)($_GET['plan']??0)]);
if(!$plan||!$plan['active']||!$plan['carrier_active']||$plan['verify_pricing']||!checkout_ready()){http_response_code(409);page_header('Checkout availability');page_intro('ALMOST THERE','This refill is not ready for checkout.','Please browse available options or contact our team to confirm eligibility.');echo '<div class="container section compact"><a class="button primary" href="/carriers">Browse carriers</a></div>';page_footer();return;}
$previous=authorized_order($_SESSION['last_checkout_order']??'');
if($previous&&in_array($previous['payment_status'],['paid','partially_refunded','refunded'],true)){
    unset($_SESSION['checkout_key'],$_SESSION['last_checkout_order']);
}
$_SESSION['checkout_key']??=bin2hex(random_bytes(32));page_header('Secure checkout','Review your prepaid refill and pay securely through Stripe.',true);page_intro('ONE LAST STEP','Let’s keep you connected.','Review your number and refill before continuing to secure payment.'); ?>
<section class="container section compact checkout-grid"><form id="checkout-form" class="surface" method="post" action="/api/checkout"><?=csrf()?><input type="hidden" name="checkout_key" value="<?=e($_SESSION['checkout_key'])?>"><input type="hidden" name="plan_id" value="<?=$plan['id']?>"><h2>Your details</h2><?php if(stripe_mode()==='test'):?><div class="notice">Test checkout: use Stripe test cards only. No real recharge will be fulfilled.</div><?php endif;?><div id="checkout-fields"><label for="recharge-phone">Number to recharge</label><input id="recharge-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel-national" required maxlength="20" value="<?=e($_SESSION['recharge_phone']??'')?>"><small>Double-check this number. Completed recharges can’t be moved to another line.</small><label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" maxlength="150" required><label for="email">Email address</label><input id="email" type="email" name="email" autocomplete="email" required maxlength="254"><div class="form-grid"><div><label for="customer-phone">Your contact number</label><input id="customer-phone" name="customer_phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="20" required></div><div><label for="zip">US billing ZIP code</label><input id="zip" name="zip" autocomplete="postal-code" inputmode="numeric" pattern="[0-9]{5}(-[0-9]{4})?" maxlength="10" required></div></div><label class="check-label"><input type="checkbox" name="terms" value="1" required><span>I confirm this is an eligible US prepaid number on <?=e($plan['carrier_name'])?>, and accept the <a href="/terms" target="_blank" rel="noopener">terms</a> and <a href="/refund-policy" target="_blank" rel="noopener">refund policy</a>.</span></label></div><div id="payment-section" hidden><div class="payment-review" id="payment-review"></div><h2>Secure card payment</h2><div id="payment-element"></div><p class="muted">Your card details go directly to Stripe.</p></div><p id="checkout-error" class="form-error" role="alert" hidden></p><button id="checkout-submit" type="submit" class="button primary full">Continue to payment <?=icon('lock')?></button><button id="edit-details" type="button" class="text-link" hidden>Edit details</button><noscript><p>JavaScript is needed for secure card payment. Please enable it or contact support.</p></noscript></form><aside class="order-summary surface"><p class="eyebrow">YOUR TOP-UP</p><h2><?=e($plan['carrier_name'])?></h2><h3><?=e($plan['name'])?></h3><p><?=e($plan['description'])?></p><dl><div><dt>Refill</dt><dd><?=money($plan['price_cents'])?></dd></div><div><dt>Additional service fee</dt><dd>$0.00</dd></div><div class="summary-total"><dt>Total (USD)</dt><dd><?=money($plan['price_cents'])?></dd></div></dl><p class="muted">The total shown is the full charge from MI Tech Wireless. Carrier deductions or plan-specific taxes may affect how refill credit is applied.</p><div class="summary-trust"><?=icon('shield')?><span>Secure, one-time payment.<br>No subscription from us.</span></div><a class="back-link" href="/carriers/<?=e($plan['slug'])?>">← Change refill</a></aside></section><?php page_footer(); ?>
